}
@keyframes verdict-gold-bloom {
  0%,
  100% {
    filter: drop-shadow(0 0 0 transparent);
  }
  25% {
    filter: drop-shadow(0 0 12px #e8af49aa);
  }
}
.workflow-stamp {
  display: block;
  width: min(15rem, 65vw);
