  }
  to {
    opacity: 1;
    transform: scale(1) rotate(-4deg);
  }
}
@keyframes workflow-revised-impact {
  0% {
    opacity: 0;
    transform: scale(1.65) rotate(-12deg);
  }
  22%,
  75% {
    opacity: 1;
    transform: scale(1) rotate(-4deg);
  }
  100% {
    opacity: 0;
    transform: scale(1) rotate(-4deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .stamp-solar-shader,
  .rubric-grade-stamp--animated::after {
    display: none;
  }
  .rubric-grade-stamp--animated::before,
  .rubric-grade-stamp--animated.rubric-grade-stamp--a::before,
  .rubric-grade-stamp--animated.rubric-grade-stamp--highest::before,
  .workflow-stamp,
  .approval-stamp-overlay .workflow-stamp {
    animation: none;
  }
}

