/* The rubric arrives as a proof sheet, then receives its grade as an ink
   impression. Both motions acknowledge a state change rather than decorating
   routine navigation. */
.rubric-proof {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background-color: var(--color-paper-soft);
  background-image: url("/assets/rubric-proof-fibers.png");
  background-size: 24rem 24rem;
}
.rubric-proof::after {
  position: absolute;
  z-index: 0;
  inset: 0;
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--color-ink-muted) 10%, transparent);
  content: "";
  opacity: 0.6;
  pointer-events: none;
}
.rubric-proof > * {
  position: relative;
  z-index: 1;
}
.rubric-proof--fresh {
  animation: rubric-proof-settle 380ms cubic-bezier(0.16, 1, 0.3, 1) both;
  transform-origin: top center;
}

.rubric-grade-stamp {
  --stamp-rotation: -4deg;
  position: relative;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  color: var(--color-ink);
  transform: rotate(var(--stamp-rotation));
  transform-origin: center;
  isolation: isolate;
}
.rubric-grade-stamp::before {
  position: absolute;
  inset: 0;
  background: currentColor;
  content: "";
  opacity: 0.82;
  -webkit-mask: var(--rubric-stamp-image) center / contain no-repeat;
  mask: var(--rubric-stamp-image) center / contain no-repeat;
  mix-blend-mode: multiply;
  z-index: 1;
}
.rubric-grade-stamp--compact {
  width: 5.5rem;
