  animation: none;
}
.dossier-filed-confirmation__paper .workflow-stamp {
  margin-block: -2rem;
}

@keyframes rubric-proof-settle {
  from {
    filter: contrast(0.96) brightness(1.025);
    transform: translateY(-4px) scaleY(0.992);
  }
  to {
    filter: contrast(1) brightness(1);
    transform: translateY(0) scaleY(1);
  }
}

/* Approach, contact at 160ms, a brief compression, then a clean lift. */
@keyframes stamp-die-press {
  0% {
    opacity: 0;
    transform: translate(14%, -48%) rotate(-10deg) scale(1.12);
    animation-timing-function: cubic-bezier(0.55, 0, 0.85, 0.55);
  }
  14% {
    opacity: 1;
    transform: translate(8%, -27%) rotate(-5deg) scale(1.07);
    animation-timing-function: cubic-bezier(0.55, 0, 0.85, 0.55);
  }
  32% {
    opacity: 1;
    transform: translate(0, 0) rotate(0) scale(1);
  }
  41% {
    transform: translate(0, 1%) rotate(0) scale(1.015, 0.975);
  }
  52% {
    transform: translate(0, 0) rotate(0) scale(1);
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  76% {
    opacity: 1;
    transform: translate(4%, -19%) rotate(3deg) scale(1.025);
  }
  100% {
    opacity: 0;
    transform: translate(14%, -48%) rotate(8deg) scale(1.07);
  }
}
@keyframes stamp-ink-settle {
  0%, 31% {
    opacity: 0;
    transform: scale(0.988);
  }
  32% {
    opacity: 1;
    transform: scale(0.988);
    filter: blur(0.35px);
  }
  54% {
    opacity: 0.98;
    transform: scale(1.004);
    filter: blur(0.15px);
  }
  100% {
    opacity: 0.88;
    transform: scale(1);
    filter: blur(0);
  }
}
@keyframes stamp-contact-shadow {
  0% {
    opacity: 0;
    transform: translate(8%, 4%) scale(1.3);
  }
  20% {
    opacity: 0.12;
    transform: translate(3%, 2%) scale(1.12);
  }
  32%, 52% {
    opacity: 0.24;
    transform: translate(0, 0) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(8%, 4%) scale(1.3);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ink-stamp__tool,
  .ink-stamp__contact-shadow {
    display: none;
  }
  .ink-stamp--pressing .ink-stamp__imprint,
  .rubric-proof--fresh {
    animation: none;
  }
}

