                      <span class="block text-[0.6rem] text-[var(--color-ink-muted)]">
                        Show the printable text boundary
                      </span>
                    </span>
                    <input
                      type="checkbox"
                      class="compositor-checkbox"
                      checked={store.layout.showMarginGuides === true}
                      onChange$={(e) =>
                        emitLayout({
                          ...store.layout,
                          showMarginGuides: (e.target as HTMLInputElement)
                            .checked,
